CREATE PROCEDURE sp_copy_from_psql_devjan02 AS /** ## Procedure Name       *[toast].[dbo].[sp_copy_from_psql_devjan02]*   **Procedure Type**      *function / stored procedure*   **Author**              Wilson, Don < dwilson@newks.com >   **Version**             1   **Created**             20251223   **Summary**   *Simple import of data pre-processed in postgresql on dev-jan02.   This is to save time for the overnight sales poll.   Without this pre-processing, it typically takes 4+ hours to pull from   API and inject directly into production tables.*      ### Change History   **Change Date:**            *YYYYMMDD*   **Author:**                 *Last, First < email address >*   **Version**:                ##   **Change:**   *detail change here*      -------------------     **/ BEGIN     -- SET NOCOUNT ON added to prevent extra result sets from     -- interfering with SELECT statements.     SET NOCOUNT ON;      declare          -- If this is for a table build, then Tab, if not, then Proc         @RunType varchar(4) = 'Proc'          -- The time the procedure begins running        ,@StartTime datetime = getdate()        -- The database the procedure is running in        ,@DBName varchar(150) = DB_NAME()        -- The name of the procedure itself        ,@ProcName varchar(150) = OBJECT_NAME(@@PROCID)        -- Default the error information to no error        ,@ErrorNumber int = 0        ,@ErrorMessage varchar(250) = ''        ,@ErrorLine int = 0             BEGIN TRY                 -- if this is a table build, perform it as a transaction         if (@RunType = 'Tab') begin transaction;          declare @Params varchar(2000) = (select 'None' as Params for json path)          insert into toast.dbo.hstitem_temp (dateofbusiness, storeid, storenum, orderid, checkid, daypart, daypartid, selectionid, parentguid,              itemguid, parentid, itemid, modificationid, modifieritemid, submodificationid, submodifieritemid, deferred, premodifier, quantity,                  salescategoryguid, ordermode, price, discpric, tax, taxinclusion, systemtime, voided, voiddate, voidreason, applieddiscountamount, MenuItemMLI, ParentMLI)         select dateofbusiness, storeid, storenum, orderid, checkid, daypart, daypartid, selectionid, parentguid, itemguid, parentid, itemid, modificationid,              modifieritemid, submodificationid, submodifieritemid, deferred, premodifier, quantity, salescategoryguid, ordermode, price, discpric, tax,              taxinclusion, systemtime, voided, voiddate, voidreason, applieddiscountamount, menuitemmli, parentmli         from [psql].[toast].[public].[hstitem_temp];                  insert into toast.dbo.hstAppliedDiscounts_temp         select *         from [psql].[toast].[public].[hstapplieddiscounts];                  merge toast.dbo.hstAppliedDiscounts ad         using toast.dbo.hstAppliedDiscounts_temp adt         on ad.AppliedDiscountID = adt.AppliedDiscountID         when matched then update set             DateOfBusiness = adt.DateOfBusiness,             StoreID = adt.StoreID,             StoreNum = adt.StoreNum,             OrderID = adt.OrderID,             CheckID = adt.CheckID,             Approver = adt.Approver,             LoyaltyVendor = adt.LoyaltyVendor,             LoyaltyReference = adt.LoyaltyReference,             DiscountID = adt.DiscountID,             DiscountType = adt.DiscountType,             DiscountName = adt.DiscountName,             DiscountPercent = adt.DiscountPercent,             DiscountAmount = adt.DiscountAmount,             AppliedPromoCode = adt.AppliedPromoCode,             NonTaxDiscountAmount = adt.NonTaxDiscountAmount         when not matched by target then          insert(AppliedDiscountID, DateOfBusiness, StoreID, StoreNum, OrderID, CheckID, Approver, LoyaltyVendor, LoyaltyReference, DiscountID, DiscountType, DiscountName, DiscountPercent, DiscountAmount, AppliedPromoCode, NonTaxDiscountAmount)         values(adt.AppliedDiscountID,adt.DateOfBusiness,adt.StoreID,adt.StoreNum,adt.OrderID,adt.CheckID,adt.Approver,adt.LoyaltyVendor,adt.LoyaltyReference,adt.DiscountID,adt.DiscountType,adt.DiscountName,adt.DiscountPercent,adt.DiscountAmount,adt.AppliedPromoCode,adt.NonTaxDiscountAmount);                  truncate table toast.dbo.hstAppliedDiscounts_temp;                  insert toast.dbo.hstCheck_temp         select *         from [psql].[toast].[public].[hstcheck];                          merge toast.dbo.hstcheck ad         using toast.dbo.hstcheck_temp adt         on ad.CheckID = adt.CheckID         when matched then update set             DateOfBusiness = adt.DateOfBusiness,             DayPart = adt.DayPart,             StoreID = adt.StoreID,             StoreNum = adt.StoreNum,             OrderID = adt.OrderID,             DisplayNumber = adt.DisplayNumber,             PaymentStatus = adt.PaymentStatus,             TabName = adt.TabName,             TaxExempt = adt.TaxExempt,             TaxExemptState = adt.TaxExemptState,             TaxExemptNumber = adt.TaxExemptNumber,             Amount = adt.Amount,             DiscountAmount = adt.DiscountAmount,             TotalAmount = adt.TotalAmount,             TaxAmount = adt.TaxAmount,             CreatedDevice = adt.CreatedDevice,             CustomerID = adt.CustomerID,             LastModifiedDevice = adt.LastModifiedDevice,             OrderMode = adt.OrderMode,             CreatedTime = adt.CreatedTime,             OpenedTime = adt.OpenedTime,             ClosedTime = adt.ClosedTime,             ModifiedTime = adt.ModifiedTime,             Deleted = adt.Deleted,             DeletedTime = adt.DeletedTime,             Voided = adt.Voided,             VoidTime = adt.VoidTime         when not matched by target then          insert(CheckID, DateOfBusiness, DayPart, StoreID, StoreNum, OrderID, DisplayNumber, PaymentStatus, TabName, TaxExempt, TaxExemptState, TaxExemptNumber, Amount, DiscountAmount,              TotalAmount, TaxAmount, CreatedDevice, CustomerID, LastModifiedDevice, OrderMode, CreatedTime, OpenedTime, ClosedTime, ModifiedTime, Deleted, DeletedTime, Voided, VoidTime)         values(adt.CheckID, adt.DateOfBusiness, adt.DayPart, adt.StoreID, adt.StoreNum, adt.OrderID, adt.DisplayNumber, adt.PaymentStatus, adt.TabName, adt.TaxExempt, adt.TaxExemptState,              adt.TaxExemptNumber, adt.Amount, adt.DiscountAmount, adt.TotalAmount, adt.TaxAmount, adt.CreatedDevice, adt.CustomerID, adt.LastModifiedDevice, adt.OrderMode, adt.CreatedTime,                  adt.OpenedTime, adt.ClosedTime, adt.ModifiedTime, adt.Deleted, adt.DeletedTime, adt.Voided, adt.VoidTime);                  truncate table toast.dbo.hstcheck_temp;                  insert into toast.dbo.hstOrder_temp         select *         from [psql].[toast].[public].[hstorder];                          merge toast.dbo.hstOrder ad         using toast.dbo.hstOrder_temp adt         on ad.OrderID = adt.OrderID         when matched then update set             DateOfBusiness = adt.DateOfBusiness,             StoreID = adt.StoreID,             StoreNum = adt.StoreNum,             RevenueCenter = adt.RevenueCenter,             OrderMode = adt.OrderMode,             Server = adt.Server,             DisplayNumber = adt.DisplayNumber,             LastModifiedDevice = adt.LastModifiedDevice,             Source = adt.Source,             Duration = adt.Duration,             DayPart = adt.DayPart,             ExcessFood = adt.ExcessFood,             Tab = adt.Tab,             RequiredPrepTime = adt.RequiredPrepTime,             ApprovalStatus = adt.ApprovalStatus,             CreatedDevice = adt.CreatedDevice,             NumberOfGuests = adt.NumberOfGuests,             ChannelID = adt.ChannelID,             PricingFeatures = adt.PricingFeatures,             CreatedDate = adt.CreatedDate,             OpenedDate = adt.OpenedDate,             EstimatedFulfillmentDate = adt.EstimatedFulfillmentDate,             ClosedDate = adt.ClosedDate,             Deleted = adt.Deleted,             DeletedDate = adt.DeletedDate,             ModifiedDate = adt.ModifiedDate,             PromisedDate = adt.PromisedDate,             Voided = adt.Voided,             VoidDate = adt.VoidDate,             VoidBusinessDate = adt.VoidBusinessDate         when not matched by target then          insert(OrderID, DateOfBusiness, StoreID, StoreNum, RevenueCenter, OrderMode, Server, DisplayNumber, LastModifiedDevice, Source, Duration, DayPart, ExcessFood, Tab, RequiredPrepTime, ApprovalStatus,              CreatedDevice, NumberOfGuests, ChannelID, PricingFeatures, CreatedDate, OpenedDate, EstimatedFulfillmentDate, ClosedDate, Deleted, DeletedDate, ModifiedDate, PromisedDate, Voided, VoidDate, VoidBusinessDate)         values(adt.OrderID, adt.DateOfBusiness, adt.StoreID, adt.StoreNum, adt.RevenueCenter, adt.OrderMode, adt.Server, adt.DisplayNumber, adt.LastModifiedDevice, adt.Source, adt.Duration, adt.DayPart,              adt.ExcessFood, adt.Tab, adt.RequiredPrepTime, adt.ApprovalStatus, adt.CreatedDevice, adt.NumberOfGuests, adt.ChannelID, adt.PricingFeatures, adt.CreatedDate, adt.OpenedDate, adt.EstimatedFulfillmentDate,              adt.ClosedDate, adt.Deleted, adt.DeletedDate, adt.ModifiedDate, adt.PromisedDate, adt.Voided, adt.VoidDate, adt.VoidBusinessDate);                  truncate table toast.dbo.hstOrder_temp;                  insert into toast.dbo.hstPayment_temp         select *         from [psql].[toast].[public].[hstpayment];                          merge toast.dbo.hstPayment ad         using toast.dbo.hstPayment_temp adt         on ad.PaymentID = adt.PaymentID         and ad.checkid = adt.checkid         and ad.orderid = adt.orderid         when matched then update set             PaymentID = adt.PaymentID,             DateOfBusiness = adt.DateOfBusiness,             DayPart = adt.DayPart,             StoreID = adt.StoreID,             StoreNum = adt.StoreNum,             PaymentType = adt.PaymentType,             OrderID = adt.OrderID,             CheckID = adt.CheckID,             MCARepaymentAmount = adt.MCARepaymentAmount,             CreatedDevice = adt.CreatedDevice,             TenderTransactionGuid = adt.TenderTransactionGuid,             Last4Digits = adt.Last4Digits,             Refund = adt.Refund,             TipRefundAmount = adt.TipRefundAmount,             RefundTxn = adt.RefundTxn,             RefundStrategy = adt.RefundStrategy,             Server = adt.Server,             SurchargeAmount = adt.SurchargeAmount,             LastModifiedDevice = adt.LastModifiedDevice,             RefundStatus = adt.RefundStatus,             OtherPaymentID = adt.OtherPaymentID,             CardEntryMode = adt.CardEntryMode,             PaymentStatus = adt.PaymentStatus,             Amount = adt.Amount,             TipAmount = adt.TipAmount,             AmountTendered = adt.AmountTendered,             CardType = adt.CardType,             HouseAccount = adt.HouseAccount,             CardProcessorType = adt.CardProcessorType,             PaidTime = adt.PaidTime,             PaidBusinessDate = adt.PaidBusinessDate,             RefundTime = adt.RefundTime,             RefundBusinessDate = adt.RefundBusinessDate,             PaymentMethodID = adt.PaymentMethodID         when not matched by target then          insert(PaymentID, DateOfBusiness, DayPart, StoreID, StoreNum, PaymentType, OrderID, CheckID, MCARepaymentAmount, CreatedDevice, TenderTransactionGuid,              Last4Digits, Refund, TipRefundAmount, RefundTxn, RefundStrategy, Server, SurchargeAmount, LastModifiedDevice, RefundStatus, OtherPaymentID,              CardEntryMode, PaymentStatus, Amount, TipAmount, AmountTendered, CardType, HouseAccount, CardProcessorType, PaidTime, PaidBusinessDate,              RefundTime, RefundBusinessDate, PaymentMethodID)         values(adt.PaymentID, adt.DateOfBusiness, adt.DayPart, adt.StoreID, adt.StoreNum, adt.PaymentType, adt.OrderID, adt.CheckID, adt.MCARepaymentAmount,              adt.CreatedDevice, adt.TenderTransactionGuid, adt.Last4Digits, adt.Refund, adt.TipRefundAmount, adt.RefundTxn, adt.RefundStrategy,              adt.Server, adt.SurchargeAmount, adt.LastModifiedDevice, adt.RefundStatus, adt.OtherPaymentID, adt.CardEntryMode, adt.PaymentStatus,              adt.Amount, adt.TipAmount, adt.AmountTendered, adt.CardType, adt.HouseAccount, adt.CardProcessorType, adt.PaidTime, adt.PaidBusinessDate,              adt.RefundTime, adt.RefundBusinessDate, adt.PaymentMethodID);                  truncate table toast.dbo.hstPayment_temp;                  insert into toast.dbo.hstServiceCharges_temp         select *                 from [psql].[toast].[public].[hstservicecharges];                          merge toast.dbo.hstServiceCharges ad         using toast.dbo.hstServiceCharges_temp adt         on ad.GUID = adt.GUID         and ad.orderid = adt.orderid         and ad.checkid = adt.checkid         when matched then update set             GUID = adt.GUID,             DateOfBusiness = adt.DateOfBusiness,             StoreID = adt.StoreID,             StoreNum = adt.StoreNum,             OrderID = adt.OrderID,             CheckID = adt.CheckID,             ChargeType = adt.ChargeType,             ChargeAmount = adt.ChargeAmount         when not matched by target then          insert(GUID, DateOfBusiness, StoreID, StoreNum, OrderID, CheckID, ChargeType, ChargeAmount)         values(adt.GUID, adt.DateOfBusiness, adt.StoreID, adt.StoreNum, adt.OrderID, adt.CheckID, adt.ChargeType, adt.ChargeAmount);                  truncate table toast.dbo.hstServiceCharges_temp;                  -- If the table build has no error, then commit the transaction         if (@RunType = 'Tab') commit transaction;                          -- Log the successful completion         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName             ,@Params = @Params;                  END TRY     BEGIN CATCH         -- If there are errors and a transaction was started, roll it back         IF @@TRANCOUNT > 0         ROLLBACK TRANSACTION;                  -- Record the error details         set @ErrorNumber  = ERROR_NUMBER();         set @ErrorLine  = ERROR_LINE();         set @ErrorMessage  = ERROR_MESSAGE();                  -- Log the error         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName             ,@ErrorNumber = @ErrorNumber             ,@ErrorMessage = @ErrorMessage             ,@ErrorLine = @ErrorLine             ,@Params = @Params;         THROW;     END CATCH END